-- v5.0.3 private-note / reviewed Knowledge native write boundary.

-- Generated from lib.knowledge_native_governance; preserve applied bytes.

CREATE OR REPLACE TRIGGER CX503_KNOW_ENTITY_GUARD BEFORE INSERT OR DELETE OR UPDATE ON ENTITIES FOR EACH ROW DECLARE native_agent VARCHAR2(128); n NUMBER; BEGIN SELECT ORA_END_USER_CONTEXT.username INTO native_agent FROM DUAL; IF native_agent IS NOT NULL THEN IF INSERTING AND :NEW.ENTITY_TYPE='KNOWLEDGE' AND COALESCE(:NEW.VISIBILITY,'?')<>'PRIVATE' THEN RAISE_APPLICATION_ERROR(-20912,'Shared or reviewed Knowledge requires governed intake'); END IF; IF UPDATING AND (:OLD.ENTITY_TYPE='KNOWLEDGE' OR :NEW.ENTITY_TYPE='KNOWLEDGE') THEN IF COALESCE(:NEW.ENTITY_TYPE,'?')<>'KNOWLEDGE' OR COALESCE(:NEW.VISIBILITY,'?')<>'PRIVATE' OR COALESCE(:OLD.VISIBILITY,'?')<>'PRIVATE' THEN RAISE_APPLICATION_ERROR(-20912,'Shared or reviewed Knowledge requires governed intake'); END IF; END IF; IF (UPDATING OR DELETING) AND :OLD.ENTITY_TYPE='KNOWLEDGE' THEN SELECT COUNT(*) INTO n FROM CX_CONTINUITY_ARTIFACT_REVS r JOIN CX_CONTINUITY_ARTIFACTS a ON a.ARTIFACT_ID=r.ARTIFACT_ID WHERE r.NATIVE_ENTITY_ID=:OLD.ENTITY_ID AND a.FAMILY='KNOWLEDGE'; IF n>0 OR (DELETING AND COALESCE(:OLD.VISIBILITY,'?')<>'PRIVATE') THEN RAISE_APPLICATION_ERROR(-20912,'Shared or reviewed Knowledge requires governed intake'); END IF; END IF; END IF; END;
/

CREATE OR REPLACE TRIGGER CX503_KNOW_META_GUARD BEFORE INSERT OR DELETE OR UPDATE ON KNOWLEDGE_META FOR EACH ROW DECLARE native_agent VARCHAR2(128); n NUMBER; BEGIN SELECT ORA_END_USER_CONTEXT.username INTO native_agent FROM DUAL; IF native_agent IS NOT NULL THEN SELECT COUNT(*) INTO n FROM CX_CONTINUITY_ARTIFACT_REVS r JOIN CX_CONTINUITY_ARTIFACTS a ON a.ARTIFACT_ID=r.ARTIFACT_ID WHERE (r.NATIVE_ENTITY_ID=:OLD.ENTITY_ID OR r.NATIVE_ENTITY_ID=:NEW.ENTITY_ID) AND a.FAMILY='KNOWLEDGE'; IF n>0 THEN RAISE_APPLICATION_ERROR(-20912,'Shared or reviewed Knowledge requires governed intake'); END IF; END IF; END;
/

CREATE OR REPLACE TRIGGER CX503_KNOW_POLICY_GUARD BEFORE INSERT OR DELETE OR UPDATE ON CX_KNOWLEDGE_ACCESS_POLICIES FOR EACH ROW DECLARE native_agent VARCHAR2(128); n NUMBER; BEGIN SELECT ORA_END_USER_CONTEXT.username INTO native_agent FROM DUAL; IF native_agent IS NOT NULL THEN RAISE_APPLICATION_ERROR(-20912,'Shared or reviewed Knowledge requires governed intake'); END IF; END;
/
